import json

# Search the JSON file for any exchange rate data related to JPY
with open('/app/resources/treasury_bulletin_2010_03.json', 'r') as f:
    data = json.load(f)

# Search through the JSON for anything with JPY
def search_json(obj, path=""):
    results = []
    if isinstance(obj, dict):
        for key, value in obj.items():
            if 'jpy' in str(key).lower() or 'yen' in str(key).lower() or 'exchange' in str(key).lower():
                results.append(f"{path}.{key}: {str(value)[:100]}")
            results.extend(search_json(value, f"{path}.{key}"))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(search_json(item, f"{path}[{i}]"))
    return results

results = search_json(data)
for r in results[:20]:
    print(r)
EOF
